frappe.ui.form.on("Task", {
    refresh(frm) {
        frm.add_custom_button("Create Task", function () {

            let dialog = new frappe.ui.Dialog({
                title: "Create Task",
                fields: [
                    {
                        label: "Task Subject",
                        fieldname: "task_subject",
                        fieldtype: "Data",
                        reqd: 1
                    }
                ],
                primary_action_label: "Create Task",
                primary_action(values) {

                    frappe.call({
                        method: "practice_app.api.create_task",
                        args: {
                            task_subject: values.task_subject
                        },
                        callback: function (r) {

                            dialog.hide();

                            frappe.msgprint({
                                title: "Success",
                                indicator: "green",
                                message: `Task ${r.message} created successfully.`
                            });

                        }
                    });

                }
            });

            dialog.show();

        });
    }
});

frappe.ui.form.on('Details', {
	refresh(frm) {
		frm.add_custom_button("Change Status",()=>{
		    frm.set_value("status","Approve")
		    frm.refresh_field("status")
		})
	}
})

frappe.ui.form.on('Details', {
	refresh(frm) {
		if(frm.doc.status==="Pending"){
		    frm.add_custom_button("Approve",()=>{
		        frm.set_value("status","Approve")
		        frappe.msgprint("Employee approved successfully")
		        frm.remove_custom_button("Approve")
		    })
		}
	},
	status(frm){
		 if(frm.doc.status==="Approve"){
		        frm.remove_custom_button("Approve")
		 }
	}
})

